# Android Mount — bspwm colours. Generated by archway; do not edit.
# Sourced from ~/.config/bspwm/bspwmrc (after bspc monitor is configured).

if command -v bspc >/dev/null 2>&1; then
  bspc config normal_border_color   "@border@"
  bspc config active_border_color   "@primary@"
  bspc config focused_border_color  "@primary@"
  bspc config presel_feedback_color "@secondary@"
  bspc config window_gap            @padding@
  bspc config border_width          @border_width@
  bspc config split_ratio           0.52
fi
